{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_7e9650e3102267a48ab4d05a", "claim_ids": ["claim_4850ee8660d2809092f0d50b", "claim_d9021dcc7320bd5b8a989d52"], "query_ids": ["q_280"], "claims": [{"claim_id": "claim_4850ee8660d2809092f0d50b", "quote": "The White House initially established 10% tariffs on imports from all countries, along with higher “reciprocal” tariffs targeting nations such as China, Vietnam and members of the European Union", "url": "https://pro.stateaffairs.com/ga/politics/georgia-tariffs-cars-lockheed-china", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "10% tariffs on imports from all countries", "duty_rate": "10%", "reported_policy_status": "initially established"}}, {"claim_id": "claim_d9021dcc7320bd5b8a989d52", "quote": "The 25% auto tariff could pose a major threat to automobile titans like Hyundai and Kia that have production plants in the state", "url": "https://pro.stateaffairs.com/ga/politics/georgia-tariffs-cars-lockheed-china", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hyundai", "facility": "production plants", "tariff_program": "25% tariff on imported cars and car parts", "duty_rate": "25%", "reported_policy_status": "Remaining in effect"}}]}, {"pair_id": "conflict_a6fbdea1bcf02ff12c33299a", "claim_ids": ["claim_4800b20174305de509ef16e1", "claim_61d39b47ebb60777d567b81a"], "query_ids": ["q_281"], "claims": [{"claim_id": "claim_4800b20174305de509ef16e1", "quote": "President Donald Trump recently announced 25% tariffs on auto imports at the White House.", "url": "https://www.teslarati.com/hyundai-georgia-plant-vs-trump-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25% tariffs on auto imports"}}, {"claim_id": "claim_61d39b47ebb60777d567b81a", "quote": "Hyundai’s $7.6 billion Georgia plant dodged U.S. President Donald Trump’s recently announced tariffs on imported vehicles and auto parts.", "url": "https://www.teslarati.com/hyundai-georgia-plant-vs-trump-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hyundai Motor Group Metaplant America (HMGMA)", "facility": "Georgia plant", "tariff_program": "U.S. President Donald Trump’s recently announced tariffs on imported vehicles and auto parts", "duty_rate": "25%", "reported_policy_status": "announced"}}]}, {"pair_id": "conflict_b6ea8658d1cbe437036e37a1", "claim_ids": ["claim_61d39b47ebb60777d567b81a", "claim_656c2224370896d2f64b4418"], "query_ids": ["q_281"], "claims": [{"claim_id": "claim_61d39b47ebb60777d567b81a", "quote": "Hyundai’s $7.6 billion Georgia plant dodged U.S. President Donald Trump’s recently announced tariffs on imported vehicles and auto parts.", "url": "https://www.teslarati.com/hyundai-georgia-plant-vs-trump-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hyundai Motor Group Metaplant America (HMGMA)", "facility": "Georgia plant", "tariff_program": "U.S. President Donald Trump’s recently announced tariffs on imported vehicles and auto parts", "duty_rate": "25%", "reported_policy_status": "announced"}}, {"claim_id": "claim_656c2224370896d2f64b4418", "quote": "Because definitely all the cars that we would produce here are going to be exempted from any tariffs,” said Hyundai Motor Company CEO Jose Munoz.", "url": "https://www.teslarati.com/hyundai-georgia-plant-vs-trump-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hyundai Motor Company", "tariff_program": "exempted from any tariffs"}}]}, {"pair_id": "conflict_85ba0affb0d2fdab3bb362b5", "claim_ids": ["claim_1c37d651c18ae4a47cf24d48", "claim_4ff970e9d3b059c3eb177ede"], "query_ids": ["q_282"], "claims": [{"claim_id": "claim_1c37d651c18ae4a47cf24d48", "quote": "The Trump administration has proposed applying tariffs on imported automobiles for the purpose of pro", "url": "https://www.govinfo.gov/content/pkg/CHRG-115shrg40897/html/CHRG-115shrg40897.htm", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "proposed applying tariffs on imported automobiles", "reported_policy_status": "proposed"}}, {"claim_id": "claim_4ff970e9d3b059c3eb177ede", "quote": "The Commerce Department is currently investigating whether imports of autos and auto parts are a threat to national security, potentially subjecting the products to additional tariffs.", "url": "https://www.govinfo.gov/content/pkg/CHRG-115shrg40897/html/CHRG-115shrg40897.htm", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "additional tariffs", "legal_authority": "Commerce Department is currently investigating whether imports of autos and auto parts are a threat to national security", "affected_product": "autos and auto parts"}}]}, {"pair_id": "conflict_0354e5b1a481222c6544f07c", "claim_ids": ["claim_096ce87a2edd87e2c78e328e", "claim_a4c4c082b80235eeb3cea69c"], "query_ids": ["q_283"], "claims": [{"claim_id": "claim_096ce87a2edd87e2c78e328e", "quote": "President Donald Trump’s implementation of a sweeping 25% tariff on imported EVs and components, particularly those sourced from China", "url": "https://aspire.usu.edu/july-25-market-intelligence", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "President Donald Trump", "tariff_program": "25% tariff on imported EVs and components", "duty_rate": "25%"}}, {"claim_id": "claim_a4c4c082b80235eeb3cea69c", "quote": "Pending tariffs on Chinese imports and a 25% automobile levy are threatening global supply chains, with potential disruptions looming for the aftermarket automotive sector in Q3 2025.", "url": "https://www.linkedin.com/posts/jcmillerjr_supplychain-tariffs-automotiveaftermarket-activity-7331644499019948033-WS6f", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Pending tariffs on Chinese imports and a 25% automobile levy", "affected_product": "aftermarket automotive sector", "effective_date": "Q3 2025"}}]}, {"pair_id": "conflict_a6210d244bab0cafa60006f5", "claim_ids": ["claim_106ba8c57fae649136d69988", "claim_47fa233f5daa1df11f9d1275"], "query_ids": ["q_284"], "claims": [{"claim_id": "claim_106ba8c57fae649136d69988", "quote": "Three months later, in June, the government announced 25 percent tariffs on $50 billion worth of Chinese imports (including cars).", "url": "https://kpmg.com/kpmg-us/content/dam/kpmg/pdf/2025/navigating-future-of-localization-automotive.pdf", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25 percent tariffs on $50 billion worth of Chinese imports (including cars)", "duty_rate": "25 percent"}}, {"claim_id": "claim_47fa233f5daa1df11f9d1275", "quote": "On 9 April 2025, President Trump caved in to pressure from the stock and bond markets and reneged on his widely derided tariff policy.", "url": "https://www.automotivelogistics.media/supply-chain/automotive-logistics-and-supply-chains-in-2025-tariff-turmoil-investment-uncertainty-and-further-cost-pressures/649740", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"announcement_date": "2 April 2025", "effective_date": "9 April 2025", "reported_policy_status": "reneged"}}]}, {"pair_id": "conflict_83b05a92467f0ca8107bee4a", "claim_ids": ["claim_1137d0ade7c7734984ff66c9", "claim_88df961ee76aaae76520b3c0"], "query_ids": ["q_284"], "claims": [{"claim_id": "claim_1137d0ade7c7734984ff66c9", "quote": "From 3 May 2025, the 25% tariff will then also be applied to automotive components.", "url": "https://www.automotivelogistics.media/supply-chain/automotive-logistics-and-supply-chains-in-2025-tariff-turmoil-investment-uncertainty-and-further-cost-pressures/649740", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"effective_date": "3 May 2025"}}, {"claim_id": "claim_88df961ee76aaae76520b3c0", "quote": "From 3 April 2025, 25% tariffs on all vehicle imports – except for Canada and Mexico, where USMCA compliant parts and vehicles will remain exempt.", "url": "https://www.automotivelogistics.media/supply-chain/automotive-logistics-and-supply-chains-in-2025-tariff-turmoil-investment-uncertainty-and-further-cost-pressures/649740", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"effective_date": "3 April 2025"}}]}, {"pair_id": "conflict_6244f2fdb661c5f16f69ed0e", "claim_ids": ["claim_6090b282db8ce1e4b4308d39", "claim_73d4f02dd03d081f85d06e5b"], "query_ids": ["q_286"], "claims": [{"claim_id": "claim_6090b282db8ce1e4b4308d39", "quote": "A proposed 25 per cent US tariff on Mexican auto imports now threatens to destabilize this export-driven model, putting market share and future investment at risk.", "url": "https://www.oxfordenergy.org/wpcms/wp-content/uploads/2025/04/OEF-144.pdf", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "proposed 25 per cent US tariff", "affected_product": "Mexican auto imports", "reported_policy_status": "proposed"}}, {"claim_id": "claim_73d4f02dd03d081f85d06e5b", "quote": "threatens to destabilize this export-driven model, putting market share and future investment at risk.", "url": "https://www.oxfordenergy.org/wpcms/wp-content/uploads/2025/04/OEF-144.pdf", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "major auto manufacturers", "tariff_program": "25 per cent tariffs"}}]}, {"pair_id": "conflict_e049b97495a3320a59af898c", "claim_ids": ["claim_8422ff035225263dd9894625", "claim_97ad2525e9a8a9797fffff5d"], "query_ids": ["q_286"], "claims": [{"claim_id": "claim_8422ff035225263dd9894625", "quote": "President Trump has imposed an unprecedented and severe tariff regime which could dampen automobile demand at a critical moment when it is needed stimulate the production of regional battery metals. Alongside implementing minimum 10 per cent tariffs across the board and between 54 to 63 per cent tariffs on China (exact estimates vary), 25 per cent tariffs have been imposed on all steel, aluminium, and auto part imports (excluding USMCA compliant auto parts from Canada and Mexico).", "url": "https://www.oxfordenergy.org/wpcms/wp-content/uploads/2025/04/OEF-144.pdf", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "minimum 10 per cent"}}, {"claim_id": "claim_97ad2525e9a8a9797fffff5d", "quote": "The future of IRA tax credits—including those most relevant to manufacturing and deployment, such as the Section 45X production credit, clean electricity tax credits, and the 30D consumer EV credit—remains uncertain.", "url": "https://rhg.com/research/clean-investment-monitor-us-clean-energy-supply-chains", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"legal_authority": "IRA"}}]}, {"pair_id": "conflict_cfce9ab41dd2c02db37be561", "claim_ids": ["claim_a297793c24c91e464d871c76", "claim_d8a68fa35a8fdd1a192a7c44"], "query_ids": ["q_287"], "claims": [{"claim_id": "claim_a297793c24c91e464d871c76", "quote": "The White House initially established 10% tariffs on imports from all countries, along with higher “reciprocal” tariffs targeting nations such as China, Vietnam and members of the European Union that levy tariffs on U.S. goods.", "url": "https://pro.stateaffairs.com/ga/politics/georgia-tariffs-cars-lockheed-china", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "10% tariffs on imports from all countries", "duty_rate": "10%", "reported_policy_status": "initially established"}}, {"claim_id": "claim_d8a68fa35a8fdd1a192a7c44", "quote": "While some business leaders breathed a sigh of relief when the Trump administration announced plans last week to delay enforcing the reciprocal tariffs for 90 days, the chamber urged farmers and manufacturers to remain nimble.", "url": "https://pro.stateaffairs.com/ga/politics/georgia-tariffs-cars-lockheed-china", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "reciprocal tariffs"}}]}]}

