    "conflict_a6210d244bab0cafa60006f5": {
      "classification": "apparent_same_scope_conflict",
      "reason": "Claim 1 states tariffs were 'announced' in June. Claim 2 states the policy was 'reneged on' on April 9, 2025. Announcing a tariff contradicts reneging on it if referring to the same policy timeline.",
      "requires_current_authority_verification": false
    },
    "conflict_83b05a92467f0ca8107bee4a": {
