      "requires_current_authority_verification": false
    },
    "conflict_e049b97495a3320a59af898c": {
      "classification": "apparent_same_scope_conflict",
      "reason": "Claim 1 concerns tariffs on auto parts/steel. Claim 2 concerns IRA tax credits. These are distinct policy instruments with no direct conflict.",
      "requires_current_authority_verification": false
    },
    "conflict_cfce9ab41dd2c02db37be561": {
      "classification": "apparent_same_scope_conflict",
      "reason": "Claim 1 states reciprocal tariffs were 'initially established'. Claim 2 states plans were announced to 'delay enforcing' them. This is a progression (establishment followed by delay) rather than a contradiction.",
      "requires_current_authority_verification": false
    }
  }
}
